// Build the SDK, then run this from any cwd to regenerate the public template commitments.
import { readFileSync, writeFileSync } from 'node:fs'
import { SHARD_COUNT, shardLeaves, treePath, upperLeaves } from '../dist/studio-tree.js'

const roots = Array.from({length: SHARD_COUNT}, (_, i) => treePath(shardLeaves(i)).root)
const root = treePath(upperLeaves(roots)).root
const file = new URL('../src/studio-roots.ts', import.meta.url)
const content = [
  '// Generated by scripts/studio-tree.mjs from the market-max-ltv-v0 SDK compiler.',
  "import type { Hex } from './spec.js'",
  `export const STUDIO_MARKET_ROOT: Hex = '${root}'`,
  'export const MARKET_SHARDS: readonly Hex[] = [', ...roots.map(r => `  '${r}',`), ']', '',
].join('\n')
if (process.argv.includes('--check')) {
  const contract = readFileSync(new URL('../../../contracts/src/policies/PolicyRegistry.sol', import.meta.url), 'utf8')
  if (readFileSync(file, 'utf8') !== content || !contract.includes(`MARKET_TEMPLATE_ROOT = ${root};`)) {
    throw new Error('Studio roots differ from the compiler outputs or the deployed registry source commitment')
  }
} else writeFileSync(file, content)
console.log(`20,002 market policies · ${roots.length} subtrees · ${root}`)
